  const toLc = (heap) => {
    const out = [];
    const q = heap.length && heap[0] != null ? [0] : [];
    while (q.length) {
      const i = q.shift();
      if (i < 0) { out.push(null); continue; }
      out.push(heap[i]);
      for (const c of [2 * i + 1, 2 * i + 2]) q.push(heap[c] != null ? c : -1);
    }
    while (out.length && out[out.length - 1] === null) out.pop();
